ALTER TYPE "CreditLedgerReason" ADD VALUE IF NOT EXISTS 'CREDIT_PACK_PURCHASE';ALTER TYPE "CreditLedgerReason" ADD VALUE IF NOT EXISTS 'PROMOTIONAL_GRANT';ALTER TYPE "CreditLedgerReason" ADD VALUE IF NOT EXISTS 'EXPIRY';
CREATE TYPE "BillingInterval" AS ENUM('MONTHLY','YEARLY');CREATE TYPE "SubscriptionStatus" AS ENUM('PENDING','ACTIVE','PAST_DUE','CANCELLED','EXPIRED');CREATE TYPE "BillingOrderType" AS ENUM('SUBSCRIPTION','CREDIT_PACK','PROMOTION');CREATE TYPE "BillingOrderStatus" AS ENUM('CREATED','ATTEMPTED','PAID','FAILED','REFUNDED');CREATE TYPE "CampaignStatus" AS ENUM('DRAFT','SCHEDULED','ACTIVE','PAUSED','COMPLETED','CANCELLED');
CREATE TABLE "subscription_plans"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"code" varchar(40) UNIQUE NOT NULL,"name" varchar(80) NOT NULL,"description" varchar(500),"monthly_price_paise" int NOT NULL CHECK("monthly_price_paise">=0),"yearly_price_paise" int NOT NULL CHECK("yearly_price_paise">=0),"limits" jsonb NOT NULL DEFAULT '{}',"features" text[] NOT NULL DEFAULT '{}',"active" boolean NOT NULL DEFAULT true,"sort_order" int NOT NULL DEFAULT 0,"created_at" timestamptz(6) NOT NULL DEFAULT now(),"updated_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "subscription_plans_active_sort_order_idx" ON "subscription_plans"("active","sort_order");
CREATE TABLE "vendor_subscriptions"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"business_id" uuid NOT NULL REFERENCES "vendor_businesses"("id") ON DELETE CASCADE,"plan_id" uuid NOT NULL REFERENCES "subscription_plans"("id") ON DELETE RESTRICT,"interval" "BillingInterval" NOT NULL,"status" "SubscriptionStatus" NOT NULL DEFAULT 'PENDING',"starts_at" timestamptz(6),"ends_at" timestamptz(6),"cancelled_at" timestamptz(6),"created_at" timestamptz(6) NOT NULL DEFAULT now(),"updated_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "vendor_subscriptions_business_id_status_created_at_idx" ON "vendor_subscriptions"("business_id","status","created_at");
CREATE TABLE "credit_packs"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"name" varchar(80) NOT NULL,"credits" int NOT NULL CHECK("credits">0),"price_paise" int NOT NULL CHECK("price_paise">0),"active" boolean NOT NULL DEFAULT true,"expires_in_days" int,"sort_order" int NOT NULL DEFAULT 0,"created_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "credit_packs_active_sort_order_idx" ON "credit_packs"("active","sort_order");
CREATE TABLE "billing_orders"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"business_id" uuid NOT NULL REFERENCES "vendor_businesses"("id") ON DELETE RESTRICT,"type" "BillingOrderType" NOT NULL,"status" "BillingOrderStatus" NOT NULL DEFAULT 'CREATED',"amount_paise" int NOT NULL CHECK("amount_paise">0),"currency" varchar(3) NOT NULL DEFAULT 'INR',"idempotency_key" varchar(100) UNIQUE NOT NULL,"razorpay_order_id" varchar(80) UNIQUE,"razorpay_payment_id" varchar(80) UNIQUE,"subscription_id" uuid REFERENCES "vendor_subscriptions"("id") ON DELETE SET NULL,"credit_pack_id" uuid REFERENCES "credit_packs"("id") ON DELETE SET NULL,"metadata" jsonb NOT NULL DEFAULT '{}',"paid_at" timestamptz(6),"created_at" timestamptz(6) NOT NULL DEFAULT now(),"updated_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "billing_orders_business_id_status_created_at_idx" ON "billing_orders"("business_id","status","created_at");
CREATE TABLE "invoices"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"business_id" uuid NOT NULL REFERENCES "vendor_businesses"("id") ON DELETE RESTRICT,"order_id" uuid UNIQUE NOT NULL REFERENCES "billing_orders"("id") ON DELETE RESTRICT,"number" varchar(40) UNIQUE NOT NULL,"amount_paise" int NOT NULL,"tax_paise" int NOT NULL DEFAULT 0,"currency" varchar(3) NOT NULL DEFAULT 'INR',"issued_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "invoices_business_id_issued_at_idx" ON "invoices"("business_id","issued_at");
CREATE TABLE "payment_webhook_events"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"provider_event_id" varchar(120) UNIQUE NOT NULL,"event_type" varchar(80) NOT NULL,"payload_hash" varchar(64) NOT NULL,"processed_at" timestamptz(6),"error" varchar(1000),"received_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "payment_webhook_events_processed_at_received_at_idx" ON "payment_webhook_events"("processed_at","received_at");
CREATE TABLE "promotion_campaigns"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"business_id" uuid NOT NULL REFERENCES "vendor_businesses"("id") ON DELETE CASCADE,"city_id" uuid NOT NULL REFERENCES "locations"("id") ON DELETE RESTRICT,"locality_id" uuid REFERENCES "locations"("id") ON DELETE RESTRICT,"category_id" uuid NOT NULL REFERENCES "categories"("id") ON DELETE RESTRICT,"starts_at" timestamptz(6) NOT NULL,"ends_at" timestamptz(6) NOT NULL,"impression_limit" int NOT NULL CHECK("impression_limit">0),"click_limit" int NOT NULL CHECK("click_limit">0),"frequency_cap" int NOT NULL CHECK("frequency_cap">0),"impressions" int NOT NULL DEFAULT 0,"clicks" int NOT NULL DEFAULT 0,"status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT',"disclosure" varchar(40) NOT NULL DEFAULT 'Sponsored',"created_at" timestamptz(6) NOT NULL DEFAULT now(),"updated_at" timestamptz(6) NOT NULL DEFAULT now(),CHECK("ends_at">"starts_at"));CREATE INDEX "promotion_campaigns_city_id_category_id_status_starts_at_ends_at_idx" ON "promotion_campaigns"("city_id","category_id","status","starts_at","ends_at");CREATE INDEX "promotion_campaigns_business_id_status_idx" ON "promotion_campaigns"("business_id","status");
INSERT INTO "subscription_plans"("code","name","monthly_price_paise","yearly_price_paise","features","sort_order") VALUES('FREE','Free',0,0,ARRAY['Basic profile','Limited portfolio','Organic enquiries'],0),('STARTER','Starter',99900,999000,ARRAY['Expanded portfolio','Packages','Basic analytics'],10),('PROFESSIONAL','Professional',249900,2499000,ARRAY['Additional cities','Lead benefits','Team access'],20),('PREMIUM','Premium',499900,4999000,ARRAY['Enhanced promotions','Priority support','Advanced reporting'],30) ON CONFLICT("code") DO NOTHING;
INSERT INTO "credit_packs"("name","credits","price_paise","sort_order") VALUES('Starter credits',10,49900,10),('Growth credits',30,129900,20),('Pro credits',75,279900,30);
INSERT INTO "permissions"("code","description") VALUES('billing.manage','Manage billing configuration and refunds'),('promotion.moderate','Moderate sponsored campaigns') ON CONFLICT("code") DO NOTHING;INSERT INTO "role_permissions"("role_id","permission_id") SELECT r.id,p.id FROM "roles" r CROSS JOIN "permissions" p WHERE r.code='SUPER_ADMIN' AND p.code IN('billing.manage','promotion.moderate') ON CONFLICT DO NOTHING;
ALTER TABLE "subscription_plans" ENABLE ROW LEVEL SECURITY;ALTER TABLE "vendor_subscriptions" ENABLE ROW LEVEL SECURITY;ALTER TABLE "credit_packs" ENABLE ROW LEVEL SECURITY;ALTER TABLE "billing_orders" ENABLE ROW LEVEL SECURITY;ALTER TABLE "invoices" ENABLE ROW LEVEL SECURITY;ALTER TABLE "payment_webhook_events" ENABLE ROW LEVEL SECURITY;ALTER TABLE "promotion_campaigns" ENABLE ROW LEVEL SECURITY;REVOKE ALL ON "subscription_plans","vendor_subscriptions","credit_packs","billing_orders","invoices","payment_webhook_events","promotion_campaigns" FROM anon,authenticated;
CREATE TRIGGER payment_webhook_immutable BEFORE UPDATE OR DELETE ON "payment_webhook_events" FOR EACH ROW EXECUTE FUNCTION prevent_trust_audit_mutation();
